import type { AgreementType } from "./types";

/**
 * The sixteen Tamil deeds the office signed off, in code.
 *
 * These are not the English templates translated. They are the documents the
 * counter has always used, and they are structured differently: some are
 * numbered clause by clause, others run as continuous narrative, and the
 * blanks are filled in by hand at the counter. So they are held verbatim —
 * paragraph for paragraph, in the order the deed runs — rather than being
 * pushed through the English clause engine, which would renumber and reorder
 * them into something the office would not recognise.
 *
 * Extracted from final-tamil-doc/templates, which is the master copy. Change
 * the Word file, re-extract, do not hand-edit the strings here.
 */

export interface TamilBlock {
  /** The paragraph, exactly as the deed has it, blanks and all. */
  text: string;
  /** Centred in the Word template — a title or a section heading. */
  heading?: boolean;
}

export interface TamilTemplate {
  id: TamilTemplateId;
  /** The instrument it is closest to, for stamp duty and routing. */
  baseType: AgreementType;
  /** What the deed is called, in Tamil. */
  nameTa: string;
  /** The same, in English, so the catalogue is searchable either way. */
  nameEn: string;
  roleA: string;
  /** Empty for the one-sided declarations — an affidavit has no second party. */
  roleB: string;
  body: TamilBlock[];
}

export type TamilTemplateId =
  | "ta-house-rent"
  | "ta-shop-rent"
  | "ta-office-rent"
  | "ta-house-lease"
  | "ta-general-lease"
  | "ta-rent-renewal"
  | "ta-loan"
  | "ta-mortgage-loan"
  | "ta-sale-agreement"
  | "ta-absolute-sale"
  | "ta-vehicle-sale"
  | "ta-indemnity"
  | "ta-affidavit"
  | "ta-noc"
  | "ta-construction"
  | "ta-business-advance"
  ;

